// Demo photos per catalog exercise (start and end position), generated by
// scripts/catalog/build-media.mjs from free-exercise-db (public domain).
import media from "@/data/exercise-media.json";

export interface ExerciseMedia {
  /** 1 frame for isometric holds, 2 (start, end) for movements. */
  frames: string[];
}

const BY_ID = media.exercises as Record<string, ExerciseMedia & { source: string }>;

export const MEDIA_CREDIT = "Fotos: Free Exercise DB (dominio público)";
export const MEDIA_SOURCE_URL = media.meta.url;

/** Custom exercises and the few without a faithful photo return null. */
export function exerciseMedia(exerciseId: string): ExerciseMedia | null {
  return BY_ID[exerciseId] ?? null;
}
